I. SELECT * FROM entregas WHERE id_motorista IN (SELECT id_motorista FROM motoristas WHERE categoria_habilitacao = 'E' OR id_motorista IN (SELECT id_motorista FROM veiculos WHERE tipo_veiculo = 'Caminhão'));
II. SELECT * FROM entregas WHERE id_motorista IN (SELECT m.id_motorista FROM motoristas m JOIN veiculos v ON m.id_motorista = v.id_motorista WHERE m.categoria_habilitacao = 'E' OR v.tipo_veiculo = 'Caminhão');
III. SELECT * FROM entregas WHERE id_motorista IN SELECT id_motorista FROM motoristas WHERE categoria_habilitacao = 'E' OR id_motorista = (SELECT id_motorista FROM veiculos WHERE tipo_veiculo = 'Caminhão');
